import{_ as n,a0 as a,w as r,s as l,ao as u,I as o,x as s,a1 as i,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"只有 4MB？如何修復 Etcher 和 Rufus 創建 Linux USB 後“破壞”的 USB | LCTT x X-CMD","titleTemplate":false,"description":"只有 4MB？如何修復 Etcher 和 Rufus 創建 Linux USB 後“破壞”的 USB | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"只有 4MB？如何修復 Etcher 和 Rufus 創建 Linux USB 後“破壞”的 USB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"只有 4MB？如何修復 Etcher 和 Rufus 創建 Linux USB 後“破壞”的 USB | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211029 Only 4 MB- How to Fix USB ‘Destroyed- by Etcher and Rufus After Creating Live Linux USB","title":"只有 4MB？如何修復 Etcher 和 Rufus 創建 Linux USB 後“破壞”的 USB","tag":"202111","desc":""},"relativePath":"202111/20211029 Only 4 MB- How to Fix USB ‘Destroyed- by Etcher and Rufus After Creating Live Linux USB.md","filePath":"[post].md"}'),m={name:"202111/20211029 Only 4 MB- How to Fix USB ‘Destroyed- by Etcher and Rufus After Creating Live Linux USB.md"};function d(c,t,f,w,h,B){const e=a("Link");return r(),l("div",null,[t[15]||(t[15]=u('<h1 id="只有-4mb-如何修復-etcher-和-rufus-創建-linux-usb-後-破壞-的-usb" tabindex="-1">只有 4MB？如何修復 Etcher 和 Rufus 創建 Linux USB 後“破壞”的 USB <a class="header-anchor" href="#只有-4mb-如何修復-etcher-和-rufus-創建-linux-usb-後-破壞-的-usb" aria-label="Permalink to “只有 4MB？如何修復 Etcher 和 Rufus 創建 Linux USB 後“破壞”的 USB”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202111/07/165254zlhgz6an6vgpv2qd.jpg" alt=""></p><p>情況是這樣的。你用 Etcher 或者 Rufus 工具在 Windows 或者 Linux 中創建了一個可啓動的、Live Linux USB。</p><p>你用它來安裝 Linux，USB 的目的已經達到了。現在你想格式化這個 USB，用它來進行常規的數據傳輸或存儲。</p><p>你把它插入你的 Windows 系統，令你吃驚的是，這個 USB 的磁盤容量只有 4MB。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/usb-drive-4mb-space-only.webp?resize=800%2C324&amp;ssl=1" alt=""></p><p>你試圖格式化它，但它可能不會讓你這麼做。即使你設法格式化它，USB 的大小現在也從通常的 8GB、16GB 或 32GB 縮減到只有 4MB。</p><p>你失去了你的 USB 嗎？並非如此。你的 USB 並沒有完全被破壞。你仍然可以用一個小技巧來格式化它，並舒適地使用它。</p><p>讓我告訴你如何在 Windows 和 Linux 中把可啓動的 USB 恢復到可用的狀態。</p><h3 id="格式化由-rufus-或-etcher-創建的-live-linux-usb-在-windows-下" tabindex="-1">格式化由 Rufus 或 Etcher 創建的 Live Linux USB （在 Windows 下） <a class="header-anchor" href="#格式化由-rufus-或-etcher-創建的-live-linux-usb-在-windows-下" aria-label="Permalink to “格式化由 Rufus 或 Etcher 創建的 Live Linux USB （在 Windows 下）”">​</a></h3><p>你在 Windows 中看到只有 4MB 的磁盤空間。你知道為什麼嗎？因為在創建 Live Linux USB 時，該工具在 FAT32 文件系統中創建了一個 4MB 的 EFI 分區。其他的分區是在 Linux 的 Ext4 文件系統中，而這是不被 Windows 識別的。</p><p>這就是為什麼你的 Windows 系統只看到 4MB 的 EFI 分區，並顯示 USB 大小為 4MB。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/mystery-behind-4-mb-linux-live-usb.webp?resize=800%2C400&amp;ssl=1" alt="Windows only see the EFI partition on the USB"></p><p>總而言之，你需要做的是刪除 USB 盤上的所有分區，用刪除現有分區後得到的空閒空間創建一個新的 NTFS 或 FAT32 分區。這就行了。</p><p>讓我展示一下詳細的步驟。</p><h4 id="步驟-1" tabindex="-1">步驟 1： <a class="header-anchor" href="#步驟-1" aria-label="Permalink to “步驟 1：”">​</a></h4><p>進入 Windows 菜單，尋找“磁盤管理”工具。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/start-disk-management-tool-windows.webp?resize=800%2C694&amp;ssl=1" alt="Start disk management tool"></p><p>啓動這個工具，它將顯示你電腦上存在的所有磁盤。當然，這包括插入的 USB。</p><p><strong>選擇正確的磁盤是非常重要的</strong>。從 U 盤的大小或“可移動”的標籤中辨別出它是哪一個。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/identify-usb-disk-in-windows.webp?resize=800%2C509&amp;ssl=1" alt=""></p><h4 id="步驟-2" tabindex="-1">步驟 2： <a class="header-anchor" href="#步驟-2" aria-label="Permalink to “步驟 2：”">​</a></h4><p>我們的想法是刪除 U 盤上的任何現有分區。未分配的空間不能被刪除，但這也沒關係。</p><p>在該分區上點擊右鍵，然後點擊“<ruby>刪除卷<rt>Delete Volume</rt></ruby>”。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/delete-partitions-on-usb-disk.webp?resize=800%2C464&amp;ssl=1" alt="Delete partitions on the USB disk"></p><p>當要求你確認時，按“<ruby>是<rt>Yes</rt></ruby>”。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/confirm-deletion-of-partition.webp?resize=800%2C357&amp;ssl=1" alt="Confirm deletion of partition"></p><p>你的目標是隻有一個未分配的空間塊。當你看到它時，右擊它並點擊“<ruby>新建簡單卷……<rt>New Simple Volume...</rt></ruby>”來創建一個分區。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/Create-New-Partition.webp?resize=800%2C471&amp;ssl=1" alt="Create New Simple Volume partition"></p><p>接下來的步驟很簡單。點擊“<ruby>下一步<rt>Next &gt;</rt></ruby>”，選擇整個可用空間，給它分配一個字母，選擇文件系統（FAT32 或 NTFS），並將其格式化。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/creating-new-simple-volume-1.png?resize=731%2C590&amp;ssl=1" alt="Click Next"></p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/creating-new-simple-volume-2.png?resize=735%2C589&amp;ssl=1" alt="Use entire available space"></p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/creating-new-simple-volume-3.png?resize=732%2C590&amp;ssl=1" alt="Give it a drive letter"></p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/creating-new-simple-volume-4.png?resize=669%2C527&amp;ssl=1" alt="Use FAT 32 or NTFS, Name the USB if you want"></p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/creating-new-simple-volume-5.png?resize=670%2C524&amp;ssl=1" alt="Revise all the changes"></p><p>完成後，你會看到 USB 已經恢復到正常狀態，你可以開始向它複製粘貼數據。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/10/live-Linux-USB-formatted-successfully.webp?resize=800%2C571&amp;ssl=1" alt="USB is back to normal state"></p><p>你現在可以像以前一樣使用你的 USB 了。</p><p>這些步驟是針對 Windows 的。如果你使用 Linux 呢？</p><h3 id="在-linux-上格式化-live-usb" tabindex="-1">在 Linux 上格式化 Live USB <a class="header-anchor" href="#在-linux-上格式化-live-usb" aria-label="Permalink to “在 Linux 上格式化 Live USB”">​</a></h3><p>我注意到，由 Etcher 和這類工具創建的 Live USB 經常拒絕被文件管理器中的右鍵格式化選項正確格式化。</p><p>除此之外，你可以像在 Windows 中那樣做：刪除現有的分區，用整個可用空間創建一個新的分區。</p><p>這裏使用 GNOME “磁盤” 工具。它已經安裝在 Ubuntu 和許多其他 Linux 發行版上。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/start-disk-app.webp?resize=791%2C256&amp;ssl=1" alt="Start disk app"></p><p><strong>同樣，確保你在這裏選擇了外部 USB 盤。</strong></p><p>你會看到 U 盤上的各種分區。試着從上面的菜單中格式化該磁盤。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/10/format-usb-in-disks-tool.webp?resize=800%2C434&amp;ssl=1" alt="Format disk"></p><p><strong>如果這不起作用，逐個刪除分區</strong>，然後把整個 USB 作為自由空間。</p><p>當你創建了整個自由空間後，點擊 “+” 號，在上面創建一個 NTFS 或 FAT32 文件系統的分區。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/10/create-partition-on-usb.webp?resize=800%2C418&amp;ssl=1" alt=""></p><p>用 NTFS（或 FAT32）創建分區，給它起個合適的名字，然後你就可以像以前一樣使用這個 USB 了。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>像 Rufus 和 Etcher 這樣的工具並沒有真正破壞你的 USB。這就是它們的功能，通過在磁盤上創建一個不同的文件系統。但這樣一來，Windows 操作系統就不能正確理解它。</p><p>好在只需付出一點努力就可以修復。我希望你也能夠修復它。如果沒有，請與我分享你的問題，我將盡力幫助你。</p><hr>',55)),o("p",null,[t[1]||(t[1]=s("via: ",-1)),i(e,{href:"https://itsfoss.com/format-live-linux-usb/"},{default:p(()=>[...t[0]||(t[0]=[s("https://itsfoss.com/format-live-linux-usb/",-1)])]),_:1})]),o("p",null,[t[6]||(t[6]=s("作者：",-1)),i(e,{href:"https://itsfoss.com/author/abhishek/"},{default:p(()=>[...t[2]||(t[2]=[s("Abhishek Prakash",-1)])]),_:1}),t[7]||(t[7]=s(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[3]||(t[3]=[s("lujun9972",-1)])]),_:1}),t[8]||(t[8]=s(" 譯者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...t[4]||(t[4]=[s("geekpi",-1)])]),_:1}),t[9]||(t[9]=s(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[5]||(t[5]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[12]||(t[12]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[10]||(t[10]=[s("LCTT",-1)])]),_:1}),t[13]||(t[13]=s(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...t[11]||(t[11]=[s("Linux中國",-1)])]),_:1}),t[14]||(t[14]=s(" 榮譽推出",-1))])])}const g=n(m,[["render",d]]);export{x as __pageData,g as default};
